// Benign baseline: a normal large-ish bundled index.js (Webpack-style).
// No campaign-unique anchors, no credential-target list co-occurrences.
// Padded to land in the rule's size band.

"use strict";

const path = require("path");
const fs = require("fs");

function compose(...fns) {
    return (x) => fns.reduceRight((v, f) => f(v), x);
}

class EventBus {
    constructor() { this.listeners = new Map(); }
    on(event, fn) {
        const list = this.listeners.get(event) || [];
        list.push(fn);
        this.listeners.set(event, list);
    }
    emit(event, payload) {
        for (const fn of this.listeners.get(event) || []) fn(payload);
    }
}

module.exports = { compose, EventBus };

